<?php use App\Core\Csrf; use App\Core\View; ?>
<div class="page-header"><div><p class="eyebrow">전도지·초대장 관리자</p><h1>행사·신청자</h1><p class="muted">초대장별 신청 현황을 한곳에서 확인합니다.</p></div><a class="button primary" href="/admin/invitations/create">행사 초대장 만들기</a></div>
<?php if($success): ?><div class="alert alert-success"><?= View::e($success) ?></div><?php endif; ?>
<div class="cards"><?php foreach($events as $event): ?><article class="card"><span><?= View::e($event['title']) ?></span><strong><?= number_format((int)$event['application_count']) ?>건</strong><small>참석 <?= number_format((int)$event['attendee_count']) ?>명 · 신규 <?= number_format((int)$event['new_count']) ?>건</small><a href="/admin/events?invitation_id=<?= (int)$event['id'] ?>">신청자 보기</a> <a href="/admin/events/<?= (int)$event['id'] ?>/questions">질문 관리</a></article><?php endforeach; ?><?php if($events===[]): ?><article class="card"><span>등록된 행사가 없습니다.</span></article><?php endif; ?></div>
<section class="panel"><h2>통합 신청자 목록</h2><form method="get" action="/admin/events" class="form-grid"><label>검색<input name="q" maxlength="100" value="<?= View::e($filters['q']) ?>" placeholder="이름·전화·이메일"></label><label>행사<select name="invitation_id"><option value="0">전체</option><?php foreach($events as $event): ?><option value="<?= (int)$event['id'] ?>" <?= (int)$filters['invitation_id']===(int)$event['id']?'selected':'' ?>><?= View::e($event['title']) ?></option><?php endforeach; ?></select></label><label>상태<select name="status"><option value="">전체</option><?php foreach(['new'=>'신규','confirmed'=>'확인','cancelled'=>'취소'] as $value=>$label): ?><option value="<?= $value ?>" <?= $filters['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button type="submit">조회</button></form>
<div class="table-wrap"><table><thead><tr><th>행사</th><th>신청자</th><th>연락처</th><th>인원</th><th>신청일</th><th>접수 상태</th><th>출석</th></tr></thead><tbody><?php foreach($applications as $application): ?><tr><td><?= View::e($application['invitation_title']) ?></td><td><strong><?= View::e($application['applicant_name']) ?></strong><?php if(!empty($application['is_waitlisted'])): ?><br><span class="badge badge-warning">대기</span><?php endif; ?><br><small><?= View::e($application['message']??'') ?></small></td><td><?= View::e($application['phone']??'-') ?><br><small><?= View::e($application['email']??'') ?></small></td><td><?= (int)$application['attendee_count'] ?></td><td><?= View::e($application['created_at']) ?></td><td><form method="post" action="/admin/events/<?= (int)$application['invitation_id'] ?>/applications/<?= (int)$application['id'] ?>/status" class="inline-form"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><select name="status"><?php foreach(['new'=>'신규','confirmed'=>'확인','cancelled'=>'취소'] as $value=>$label): ?><option value="<?= $value ?>" <?= $application['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button type="submit">저장</button></form></td><td><form method="post" action="/admin/events/<?= (int)$application['invitation_id'] ?>/applications/<?= (int)$application['id'] ?>/attendance" class="inline-form"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><select name="attendance_status"><?php foreach(['unknown'=>'미확인','attended'=>'참석','absent'=>'결석'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($application['attendance_status']??'unknown')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button type="submit">저장</button></form></td></tr><?php endforeach; ?><?php if($applications===[]): ?><tr><td colspan="7" class="empty">조건에 맞는 신청자가 없습니다.</td></tr><?php endif; ?></tbody></table></div></section>
